import { endpoint, event, invoke, machine, mutation, on, query, ui } from '@hozu/core'
import { z } from 'zod'
import { home, login } from '../../routes.ts'

export const Session = z.object({ user: z.string() })
export const Name = z.object({ name: z.string().regex(/^\s*[A-Za-z]{2,20}\s*$/, 'Use 2–20 letters') })

export const SignIn = event({ payload: z.object({ name: z.string() }) })
export const SignOut = event({ payload: z.object({}) })
export const DeleteAccount = event({ payload: z.object({}) })

export const me = query({
  input: z.object({}),
  output: z.object({ name: z.string() }),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  runs: 'server',
  access: 'anyone',
})

// `/` only sends the visitor on: to the notes when signed in, to the sign-in page otherwise.
export const start = endpoint({ method: 'GET', path: '/', input: z.object({}), output: 'redirect' })

export const signIn = mutation({ input: Name, output: z.object({}), runs: 'server', access: 'anyone' })
export const signOut = mutation({ input: z.object({}), output: z.object({}), runs: 'server', access: 'anyone' })
// Deletes every note of the signed-in user (archived ones included), forgets the user and signs out.
export const deleteAccount = mutation({ input: z.object({}), output: z.object({}), runs: 'server', access: 'anyone' })

export const accountMachine = machine({
  context: z.object({
    draft: z.string(),
    error: z.string().nullable(),
    fields: z.object({ name: z.string().nullable() }),
  }),
  initialContext: { draft: '', error: null, fields: { name: null } },
  initial: 'idle',
  states: ({ ctx }) => ({
    idle: {
      on: [
        on(SignIn, {
          target: 'signingIn',
          assign: (e) => { ctx.draft = e.name; ctx.error = null; ctx.fields = { name: null } },
        }),
        on(SignOut, { target: 'signingOut' }),
        on(DeleteAccount, { target: 'deleting', assign: () => { ctx.error = null } }),
      ],
    },
    signingIn: {
      invoke: invoke(signIn, {
        input: { name: ctx.draft },
        done: { target: 'idle', navigate: () => ui.link(home, null) },
        failed: {
          Invalid: { target: 'idle', assign: (e) => { ctx.fields = e.fields } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    signingOut: {
      invoke: invoke(signOut, {
        input: {},
        done: { target: 'idle', navigate: () => ui.link(login, null) },
        failed: { Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } } },
      }),
    },
    deleting: {
      invoke: invoke(deleteAccount, {
        input: {},
        done: { target: 'idle', navigate: () => ui.link(login, null, { deleted: true }) },
        failed: { Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } } },
      }),
    },
  }),
})
import type { Implement } from '@hozu/data'
import { ui } from '@hozu/core'
import { home, login } from '../../routes.ts'
import { deleteAccount, me, signIn, signOut, start } from './model.ts'

export function accountResolvers<Env>(implement: Implement<{ user: string }, Env>, onSignOut: (user: string) => void = () => {}, onSignIn: (user: string) => void = () => {}, onDelete: (user: string) => void = () => {}) {
  return [
    implement(me, (_, { session, fail }) => (session ? { name: session.user } : fail('Unauthorized', {}))),
    implement(start, (_, { session, redirect }) => redirect(session ? ui.link(home, null) : ui.link(login, null))),
    implement(signIn, ({ name }, { setSession }) => {
      const user = name.trim().toLowerCase()
      onSignIn(user)
      setSession({ user })
      return {}
    }),
    implement(signOut, (_, { session, setSession }) => {
      if (session) onSignOut(session.user)
      setSession(null)
      return {}
    }),
    implement(deleteAccount, (_, { session, setSession }) => {
      if (session) onDelete(session.user)
      setSession(null)
      return {}
    }),
  ]
}

