cat > features/admin/server.ts <<'EOF'
import type { Implement } from '@hozu/data'
import { listUsers, setAccess } from './model.ts'

// `owned` counts each owner's notes (archived included); `seen` is everyone who has signed in; `readOnly` holds the
// accounts the admin made read-only.
export function adminResolvers<Env>(implement: Implement<{ user: string }, Env>, owned: () => Map<string, number>, seen: Set<string>, readOnly: Set<string>) {
  return [
    implement(listUsers, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      if (session.user !== 'admin') return fail('NotAdmin', {})
      const counts = owned()
      for (const user of seen) if (!counts.has(user)) counts.set(user, 0)
      return [...counts]
        .map(([name, notes]) => ({ name, notes, readOnly: readOnly.has(name) }))
        .sort((a, b) => a.name.localeCompare(b.name))
    }),
    implement(setAccess, ({ name, access }, { session, fail }) => {
      if (!session || session.user !== 'admin') return fail('NotAdmin', {})
      const user = name.trim().toLowerCase()
      if (user === 'admin' || user === '') return fail('Invalid', { message: 'The admin account stays writable', fields: { name: 'Choose another user' } })
      if (access === 'readOnly') readOnly.add(user)
      else readOnly.delete(user)
      return {}
    }),
  ]
}
EOF
